import java.util.*;
import java.io.*;

public class Main {
    static final int P1 = 998244353;
    static final int P2 = 1000000007;
    static final int B = 1000000;
    static List<Integer>[] seqs = new ArrayList[7];
    static int[] prefixSum = new int[7];
    static long total, orderCount, result;

    static {
        for (int i = 0; i < 7; i++) {
            seqs[i] = new ArrayList<>();
        }
    }

    static void buildSequences(long start, int depth) {
        orderCount++;
        seqs[depth].add((int)((orderCount - start + P1) % P1));
        prefixSum[depth] = (prefixSum[depth] + seqs[depth].get(seqs[depth].size() - 1)) % P2;
        if (depth == 6) return;
        for (int digit = 0; digit <= 9; digit++) {
            buildSequences(start * 10 + digit, depth + 1);
        }
    }

    static void explore(long x) {
        if (x > total) return;
        if (x * B + B - 1 <= total && x * B * 10 > total) {
            long tempOrder = orderCount;
            for (int i = 0, mult = 1; i <= 6; i++, mult *= 10) {
                int size = seqs[i].size();
                int delta = (int)(((tempOrder - x * mult) % P1 + P1) % P1);
                int pos = lowerBound(seqs[i], P1 - delta);
                result = (result + 1L * delta * size + prefixSum[i]) % P2;
                result = (result - 1L * (size - pos) * P1 + P2) % P2;
                orderCount += size;
            }
            return;
        }
        orderCount++;
        result = (result + ((orderCount - x) % P1 + P1) % P1) % P2;
        for (int digit = 0; digit <= 9; digit++) {
            explore(x * 10 + digit);
        }
    }

    static int lowerBound(List<Integer> list, int value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine());
        total = n;
        buildSequences(0, 0);
        orderCount = 0;
        for (int i = 0; i <= 6; i++) {
            Collections.sort(seqs[i]);
        }
